{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "title": "ParameterValueApplyRequest",
  "type": "object",
  "description": "Bounded project-document parameter mutation contracts. A wet edit names its exact target (element id +\nparameter id) and carries the ParameterTarget evidence it was reviewed against; a stale or\nmissing Expected refuses. A dry run is the evidence read: it returns Current per edit, and is the only place\nParameterName resolves (discovery for callers that do not yet know the parameter id).\n            ",
  "additionalProperties": false,
  "required": [
    "edits"
  ],
  "properties": {
    "edits": {
      "type": "array",
      "items": {
        "$ref": "#/definitions/ParameterValueEdit"
      }
    },
    "dryRun": {
      "type": "boolean"
    },
    "transactionName": {
      "type": [
        "null",
        "string"
      ]
    }
  },
  "definitions": {
    "ParameterValueEdit": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "elementId"
      ],
      "properties": {
        "elementId": {
          "type": "integer",
          "format": "int64"
        },
        "parameterId": {
          "type": [
            "integer",
            "null"
          ],
          "format": "int64"
        },
        "parameterName": {
          "type": [
            "null",
            "string"
          ]
        },
        "value": {
          "type": [
            "null",
            "string"
          ]
        },
        "unit": {
          "type": [
            "null",
            "string"
          ]
        },
        "rawInternal": {
          "type": "boolean"
        },
        "expected": {
          "oneOf": [
            {
              "type": "null"
            },
            {
              "$ref": "#/definitions/ParameterTarget"
            }
          ]
        }
      }
    },
    "ParameterTarget": {
      "type": "object",
      "description": "Mutation evidence for one native parameter: what a reviewer saw, and what a writer compares against a fresh\nread before writing. Schedule cells carry one per target; parameter edits carry one as Expected.\n            ",
      "additionalProperties": false,
      "required": [
        "elementId",
        "parameterId",
        "storageType",
        "isReadOnly",
        "hasValue",
        "rawValue"
      ],
      "properties": {
        "elementId": {
          "type": "integer",
          "format": "int64"
        },
        "parameterId": {
          "type": "integer",
          "format": "int64"
        },
        "parameterName": {
          "type": [
            "null",
            "string"
          ]
        },
        "storageType": {
          "$ref": "#/definitions/RequestedParameterStorageType"
        },
        "isReadOnly": {
          "type": "boolean"
        },
        "hasValue": {
          "type": "boolean"
        },
        "rawValue": {
          "type": [
            "null",
            "string"
          ]
        }
      }
    },
    "RequestedParameterStorageType": {
      "type": "string",
      "description": "",
      "x-enumNames": [
        "None",
        "String",
        "Integer",
        "Double",
        "ElementId"
      ],
      "enum": [
        "None",
        "String",
        "Integer",
        "Double",
        "ElementId"
      ]
    }
  }
}

