{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "title": "ExecuteRevitScriptData",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "status",
    "output",
    "diagnostics",
    "revitVersion",
    "targetFramework",
    "executionId"
  ],
  "properties": {
    "status": {
      "$ref": "#/definitions/ScriptExecutionStatus"
    },
    "output": {
      "type": "string"
    },
    "diagnostics": {
      "type": "array",
      "items": {
        "$ref": "#/definitions/ScriptDiagnostic"
      }
    },
    "revitVersion": {
      "type": "string"
    },
    "targetFramework": {
      "type": "string"
    },
    "containerTypeName": {
      "type": [
        "null",
        "string"
      ]
    },
    "executionId": {
      "type": "string"
    },
    "artifacts": {
      "type": [
        "array",
        "null"
      ],
      "items": {
        "$ref": "#/definitions/ScriptArtifactData"
      }
    },
    "data": {
      "oneOf": [
        {},
        {
          "type": "null"
        }
      ]
    },
    "attribution": {
      "oneOf": [
        {
          "type": "null"
        },
        {
          "$ref": "#/definitions/PodReceipt"
        }
      ]
    }
  },
  "definitions": {
    "ScriptExecutionStatus": {
      "type": "string",
      "description": "",
      "x-enumNames": [
        "Succeeded",
        "ReferenceResolutionFailed",
        "CompilationFailed",
        "RuntimeFailed",
        "Rejected",
        "PolicyRejected",
        "Cancelled",
        "TimedOut"
      ],
      "enum": [
        "Succeeded",
        "ReferenceResolutionFailed",
        "CompilationFailed",
        "RuntimeFailed",
        "Rejected",
        "PolicyRejected",
        "Cancelled",
        "TimedOut"
      ]
    },
    "ScriptDiagnostic": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "stage",
        "severity",
        "message"
      ],
      "properties": {
        "stage": {
          "type": "string"
        },
        "severity": {
          "$ref": "#/definitions/ScriptDiagnosticSeverity"
        },
        "message": {
          "type": "string"
        },
        "source": {
          "type": [
            "null",
            "string"
          ]
        }
      }
    },
    "ScriptDiagnosticSeverity": {
      "type": "string",
      "description": "",
      "x-enumNames": [
        "Info",
        "Warning",
        "Error"
      ],
      "enum": [
        "Info",
        "Warning",
        "Error"
      ]
    },
    "ScriptArtifactData": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "name",
        "relativePath",
        "fullPath",
        "contentType",
        "sizeBytes"
      ],
      "properties": {
        "name": {
          "type": "string"
        },
        "relativePath": {
          "type": "string"
        },
        "fullPath": {
          "type": "string"
        },
        "contentType": {
          "type": "string"
        },
        "sizeBytes": {
          "type": "integer",
          "format": "int64"
        }
      }
    },
    "PodReceipt": {
      "type": "object",
      "description": "One run's receipt: its source origin, outcome, and outputs. `PodId` is the pod that stores the run.\n`MemberSha256` names saved bytes, so only a SavedMember run carries it; a\nsupplied draft keeps the path it drafts and its own bytes and hash stay in `input.json`; operation input\nnames no member.\n            ",
      "additionalProperties": false,
      "required": [
        "podId",
        "origin",
        "operation",
        "outcome",
        "outputs"
      ],
      "properties": {
        "podId": {
          "type": "string"
        },
        "memberPath": {
          "type": [
            "null",
            "string"
          ]
        },
        "memberSha256": {
          "type": [
            "null",
            "string"
          ]
        },
        "origin": {
          "$ref": "#/definitions/PodRunOrigin"
        },
        "operation": {
          "type": "string"
        },
        "planHash": {
          "type": [
            "null",
            "string"
          ]
        },
        "outcome": {
          "$ref": "#/definitions/PodRunOutcome"
        },
        "outputs": {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "reason": {
          "type": [
            "null",
            "string"
          ],
          "description": "A failure's text; `null` when there is none. An empty string is not a third shape, however a writer spells \"no reason\"."
        }
      }
    },
    "PodRunOrigin": {
      "type": "string",
      "description": "What a run's source was: a saved member's bytes, a supplied draft, or operation input with no member.",
      "x-enumNames": [
        "SavedMember",
        "SuppliedDraft",
        "Operation"
      ],
      "enum": [
        "SavedMember",
        "SuppliedDraft",
        "Operation"
      ]
    },
    "PodRunOutcome": {
      "type": "string",
      "description": "A run's settled outcome. Cancelled is its own answer, never a rollback claim.",
      "x-enumNames": [
        "Succeeded",
        "Failed",
        "Cancelled"
      ],
      "enum": [
        "Succeeded",
        "Failed",
        "Cancelled"
      ]
    }
  }
}
